1	use biome_analyze::{
2	    Ast, FixKind, Rule, RuleDiagnostic, RuleSource, context::RuleContext, declare_lint_rule,
3	};
4	use biome_console::markup;
5	use biome_html_syntax::{AnyHtmlElement, HtmlAttribute, HtmlAttributeList, HtmlFileSource};
6	use biome_rowan::{AstNode, BatchMutationExt, TextRange, TokenText};
