10	use crate::HtmlRuleAction;
11	
12	declare_lint_rule! {
13	    /// Disallow the use of inline styles.
14	    ///
15	    /// Inline styles via the `style` attribute make code harder to maintain and override,
16	    /// prevent reusability of styling, and can be a security concern when implementing
17	    /// a strict Content Security Policy (CSP).
18	    ///
19	    /// Instead of inline styles, use CSS classes, CSS modules, or a styling library.
20	    ///
21	    /// ## Examples
22	    ///
23	    /// ### Invalid
24	    ///
25	    /// ```html,expect_diagnostic
26	    /// <div style="color: red;"></div>
27	    /// ```
28	    ///
29	    /// ```html,expect_diagnostic
30	    /// <p style="font-size: 14px;">Hello</p>
31	    /// ```
32	    ///
33	    /// ### Valid
34	    ///
35	    /// ```html
36	    /// <div class="text-red"></div>
37	    /// ```
38	    ///
39	    /// ```html
40	    /// <p class="body-text">Hello</p>
41	    /// ```
42	    ///
43	    /// ## Resources
44	    ///
45	    /// - [Content Security Policy: Allowing inline styles](https://content-security-policy.com/examples/allow-inline-style)
46	    ///
47	    pub NoInlineStyles {
48	        version: "2.4.9",
49	        name: "noInlineStyles",
50	        language: "html",
51	        recommended: false,
52	        sources: &[
53	            RuleSource::HtmlEslint("no-inline-styles").same(),
54	        ],
55	        fix_kind: FixKind::Unsafe,
56	    }
57	}
58	
59	impl Rule for NoInlineStyles {
60	    type Query = Ast<AnyHtmlElement>;
61	    type State = TextRange;
62	    type Signals = Option<Self::State>;
63	    type Options = NoInlineStylesOptions;
64	
65	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
66	        let node = ctx.query();
67	
68	        match node {
69	            AnyHtmlElement::HtmlElement(element) => {
70	                let opening = element.opening_element().ok()?;
71	
72	                if let Some(name) = opening.tag_name()
73	                    && is_custom_component(name, ctx)
74	                {
75	                    return None;
76	                }
77	
78	                find_style_attribute(opening.attributes()).map(|attribute| attribute.range())
79	            }
80	            AnyHtmlElement::HtmlSelfClosingElement(self_closing_element) => {
81	                if let Some(name) = self_closing_element.tag_name()
82	                    && is_custom_component(name, ctx)
83	                {
84	                    return None;
85	                }
86	
87	                find_style_attribute(self_closing_element.attributes())
88	                    .map(|attribute| attribute.range())
89	            }
90	            _ => None,
91	        }
92	    }
93	
94	    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
95	        Some(
96	            RuleDiagnostic::new(
97	                rule_category!(),
98	                state,
99	                markup! {
100	                    "Unexpected "<Emphasis>"style"</Emphasis>" attribute."
101	                },
102	            )
103	            .note(markup! {
104	                "Inline styles make code harder to maintain, reduce reusability, and can prevent effective use of a strict Content Security Policy. Use external CSS classes or stylesheets instead."
105	            }),
106	        )
107	    }
108	
109	    fn action(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<HtmlRuleAction> {
110	        let node = ctx.query();
111	        let mut mutation = ctx.root().begin();
112	
113	        match node {
114	            AnyHtmlElement::HtmlElement(element) => {
115	                let opening = element.opening_element().ok()?;
116	                mutation.remove_node(find_style_attribute(opening.attributes()).unwrap())
117	            }
118	            AnyHtmlElement::HtmlSelfClosingElement(self_closing_element) => mutation
119	                .remove_node(find_style_attribute(self_closing_element.attributes()).unwrap()),
120	            _ => {}
121	        }
122	
123	        Some(HtmlRuleAction::new(
124	            ctx.metadata().action_category(ctx.category(), ctx.group()),
125	            ctx.metadata().applicability(),
126	            markup! { "Remove the "<Emphasis>"style"</Emphasis>" attribute." }.to_owned(),
127	            mutation,
128	        ))
129	    }
130	}
131	
132	fn find_style_attribute(attributes: HtmlAttributeList) -> Option<HtmlAttribute> {
133	    for attribute in attributes {
134	        if let Some(attribute) = attribute.as_html_attribute()
135	            && let Some(name) = attribute.name().ok()
136	            && let Some(value_token) = name.value_token().ok()
137	            && value_token.text_trimmed().to_lowercase_cow() == "style"
138	        {
139	            return Some(attribute.clone());
140	        }
141	    }
142	
143	    None
144	}
145	
146	fn is_custom_component(element_name: TokenText, ctx: &RuleContext<NoInlineStyles>) -> bool {
147	    let source_type = ctx.source_type::<HtmlFileSource>();
148	
149	    if source_type.is_html() {
150	        return false;
151	    }
152	
153	    element_name.text() != element_name.to_lowercase_cow()
154	}
