use biome_console::markup;
use biome_diagnostics::Severity;
use biome_html_syntax::{AnyHtmlElement, HtmlAttributeList};
use biome_rowan::{AstNode, TextRange};
use biome_rule_options::use_iframe_sandbox::UseIframeSandboxOptions;
use biome_string_case::StrOnlyExtension;

declare_lint_rule! {
    /// Enforce the use of the `sandbox` attribute on `<iframe>` elements.
    ///
    /// The `sandbox` attribute enables an extra set of restrictions for the content
    /// embedded in an `<iframe>`. Using it reduces the risk of malicious scripts and
    /// other security threats coming from the embedded content.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```html,expect_diagnostic
    /// <iframe></iframe>
    /// ```
    ///
    /// ### Valid
    ///
    /// ```html
    /// <iframe sandbox></iframe>
    /// ```
    ///
    /// ```html
    /// <iframe sandbox=""></iframe>
    /// ```
    ///
    /// ```html
    /// <iframe sandbox="allow-scripts"></iframe>
    /// ```
    ///
    pub UseIframeSandbox {
        version: "next",
        name: "useIframeSandbox",
        language: "html",
        recommended: false,
        severity: Severity::Error,
    }
}

impl Rule for UseIframeSandbox {
    type Query = Ast<AnyHtmlElement>;
    type State = TextRange;
    type Signals = Option<Self::State>;
    type Options = UseIframeSandboxOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();

        match node {
            AnyHtmlElement::HtmlElement(element) => {
                let opening = element.opening_element().ok()?;
                let name = opening.tag_name()?;
                if name.to_lowercase_cow() != "iframe" {
                    return None;
                }
                if has_sandbox_attribute(&opening.attributes()) {
                    return None;
                }
                Some(element.range())
            }
            AnyHtmlElement::HtmlSelfClosingElement(element) => {
                let name = element.tag_name()?;
                if name.to_lowercase_cow() != "iframe" {
                    return None;
                }
                if has_sandbox_attribute(&element.attributes()) {
                    return None;
                }
                Some(element.range())
            }
            _ => None,
        }
    }

    fn diagnostic(_ctx: &RuleContext<Self>, range: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                range,
                markup! {
                    "Iframe doesn't have the sandbox attribute."
                },
            )
            .note(markup! {
                "The sandbox attribute enables an extra set of restrictions for the content in the iframe, protecting against malicious scripts and other security threats."
            })
            .note(markup! {
                "Provide a sandbox attribute when using iframe elements."
            }),
        )
    }
}

fn has_sandbox_attribute(attributes: &HtmlAttributeList) -> bool {
    attributes.into_iter().any(|attribute| {
        attribute
            .as_html_attribute()
            .and_then(|attribute| attribute.name().ok())
            .and_then(|name| name.value_token().ok())
            .is_some_and(|value_token| value_token.text_trimmed().to_lowercase_cow() == "sandbox")
    })
}
