            Some(attribute) => attribute.initializer().is_some(),
            None => false,
        };
        if has_sandbox {
            return None;
        }

        match node {
            AnyJsxElement::JsxOpeningElement(_) => {
                let jsx_element = node.parent::<JsxElement>()?;
                Some(jsx_element.range())
            }
            _ => Some(node.range()),
